/**
 * icse-tamil@1: OpenPath's own ICSE (CISCE second-language) Tamil course, Classes 1-10. The questions are generated by
 * tools/tamil/build_icse.py from small authored banks, so each answer is fixed by rule. Provisional content: no mastery
 * claims, only practice progress kept on the device.
 */
import courseData from "../../../content/tamil/icse.v1.json";

export type CourseQuestion = { id: string; prompt: string; promptEn: string; options: string[]; answer: string; why?: string };
export type CourseTopic = {
  id: string;
  class: number;
  title: string;
  titleEn: string;
  teach: { ta: string; en: string; examples: string };
  questions: CourseQuestion[];
};
export const course = courseData as { schema: string; board: string; review: string; topics: CourseTopic[] };
export const CLASSES = [...new Set(course.topics.map((t) => t.class))].sort((a, b) => a - b);
export const topicsFor = (cls: number) => course.topics.filter((t) => t.class === cls);

const norm = (s: string) => s.normalize("NFC").trim();
export const isRight = (q: CourseQuestion, response: string) => norm(response) === norm(q.answer);

/** Per question: how often it was answered right and wrong. Kept on the device only. */
export type Progress = Record<string, { right: number; wrong: number }>;

export function record(progress: Progress, q: CourseQuestion, right: boolean): Progress {
  const was = progress[q.id] ?? { right: 0, wrong: 0 };
  return { ...progress, [q.id]: right ? { ...was, right: was.right + 1 } : { ...was, wrong: was.wrong + 1 } };
}

/** Share of a topic's questions the learner has answered right at least once (0..1). */
export const topicDone = (t: CourseTopic, p: Progress) => t.questions.filter((q) => (p[q.id]?.right ?? 0) > 0).length / t.questions.length;
export const classDone = (cls: number, p: Progress) => {
  const qs = topicsFor(cls).flatMap((t) => t.questions);
  return qs.filter((q) => (p[q.id]?.right ?? 0) > 0).length / qs.length;
};

/**
 * One round: up to `size` questions, not-yet-right ones first (missed ones before unseen ones), then the rest for review.
 * Deterministic for a given progress, so a round can be rebuilt after a reload.
 */
export function round(t: CourseTopic, p: Progress, size = 8): CourseQuestion[] {
  const rank = (q: CourseQuestion) => {
    const r = p[q.id];
    if (!r) return 1;
    if (r.right === 0) return 0;
    return 2 + r.right - r.wrong / 10;
  };
  return t.questions
    .map((q, i) => ({ q, i, r: rank(q) }))
    .sort((a, b) => a.r - b.r || a.i - b.i)
    .slice(0, size)
    .map((x) => x.q);
}

export function validateCourse(topics: CourseTopic[] = course.topics): string[] {
  const errors: string[] = [];
  const ids = new Set<string>();
  for (const t of topics) {
    if (!t.title || !t.teach.ta || !t.teach.en) errors.push(`${t.id}: missing teaching`);
    if (t.questions.length < 4) errors.push(`${t.id}: too few questions`);
    for (const q of t.questions) {
      if (ids.has(q.id)) errors.push(`duplicate ${q.id}`);
      ids.add(q.id);
      if (!q.options.includes(q.answer)) errors.push(`${q.id}: answer not offered`);
      if (new Set(q.options).size !== q.options.length || q.options.length < 2) errors.push(`${q.id}: bad options`);
      if (q.options.some((o) => o !== o.normalize("NFC"))) errors.push(`${q.id}: not NFC`);
    }
  }
  return errors;
}
